// client/src/features/dashboard/attendee/AttendeeDashboard.jsx
import React, { useEffect, useState } from 'react';
import axios from 'axios';
import '../../../styles/GlobalStyles.css';

const AttendeeDashboard = () => {
  const [events, setEvents]   = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState(null);

  // Fetch all events with registration/payment status
  const fetchEvents = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const res   = await axios.get('http://localhost:5000/api/attendee/events', {
        headers: { Authorization: `Bearer ${token}` }
      });
      setEvents(res.data.events);
      setError(null);
    } catch (err) {
      console.error(err);
      setError('Failed to fetch events');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchEvents();
  }, []);

  // Register for an event
  const handleRegister = async (eventId) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        'http://localhost:5000/api/attendee/register',
        { eventId },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchEvents();
    } catch (err) {
      console.error(err);
      alert('Registration failed');
    }
  };

  // Pay for a registered event
  const handlePay = async (eventId) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        `http://localhost:5000/api/attendee/pay/${eventId}`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      fetchEvents();
    } catch (err) {
      console.error(err);
      alert('Payment failed');
    }
  };

  return (
    <div className="container">
      <div className="card">
        <h2>Attendee Dashboard</h2>

        {/* Upcoming Events */}
        <section>
          <h3>Upcoming Events</h3>
          {loading ? (
            <p>Loading…</p>
          ) : error ? (
            <p style={{ color: 'red' }}>{error}</p>
          ) : (
            <ul>
              {events.map(evt => (
                <li key={evt.id} style={{ margin: '1rem 0' }}>
                  <strong>{evt.title}</strong> – {new Date(evt.date).toLocaleString()}
                  <br />
                  {!evt.isRegistered && (
                    <button className="btn" onClick={() => handleRegister(evt.id)}>
                      Register
                    </button>
                  )}
                  {evt.isRegistered && !evt.hasPaid && (
                    <button className="btn" onClick={() => handlePay(evt.id)}>
                      Pay Now
                    </button>
                  )}
                  {evt.hasPaid && (
                    <a href={evt.sessionLink} target="_blank" rel="noopener noreferrer" className="btn">
                      Join Session
                    </a>
                  )}
                </li>
              ))}
              {events.length === 0 && <p>No upcoming events.</p>}
            </ul>
          )}
        </section>
      </div>
    </div>
  );
};

export default AttendeeDashboard;
